#!/usr/bin/env python3
"""Independently author the Hist J root inquiry question bank."""
import json
from pathlib import Path
ROOT=Path(__file__).resolve().parents[1];OUT=ROOT/"questions/social";LESSON="lesson-social-content-hist-j";KG="kg-social-content-hist-j"
ITEMS=[
("小組想把主題 H、I 的知識轉成地方史考察，第一步要把『這裡的歷史如何變化？』改成可研究的問題。哪項最適當？",["老街是不是最重要？","在 1950 至 1990 年間，車站啟用是否改變某街區商店分布？可用哪些地圖與訪談檢驗？","所有居民都怎麼想？","地方文化為什麼一直很好？"],"B","問題必須限定時間、地點、關係與可取得的證據，才能讓他人重做與檢驗。","問題設計"),
("研究者拿到一張沒有日期、拍攝者和地點的老照片，畫面卻有清楚招牌。使用前最重要的是？",["直接以招牌文字推定整張照片的年代。","先查找照片來源、版本、地點與交叉證據，並標記仍無法確認的資訊。","因為沒有日期就完全丟棄所有照片。","只詢問一位熟悉地方的人便確定答案。"],"B","可辨識物件不等於來源完整；照片的形成與定位條件要先查證，結論也要保留不確定性。","照片來源"),
("兩位居民對同一市場的記憶一人說繁榮、一人說常有空店。研究者應如何處理？",["選擇說得比較詳細的一位。","把兩段記憶平均成市場一半繁榮。","比較訪談時間、位置、生活經驗與其他地圖或帳冊，說明差異本身也是資料。","只相信官方市場統計。"],"C","口述差異可能來自位置和經驗，不能任意裁決；與其他來源互證才能界定範圍。","口述史料"),
("踏查私人住家並訪問未成年人時，哪項做法符合田野倫理？",["先拍攝再請居民事後同意。","只要研究有教育目的，就不需要匿名。","取得清楚同意、監護人許可與可撤回安排，限制公開資訊並尊重拒絕。","把未成年人的話全部改寫成研究者想表達的意思。"],"C","私人空間與未成年人涉及隱私、同意、匿名和撤回權，不能以研究方便取代倫理程序。","田野倫理"),
("一張現地照片顯示市場入口換了新招牌，研究者因此宣稱整個市場已完全現代化。哪一步需要修正？",["再拍更多相同角度的入口照片即可。","把『入口有新招牌』和『整個市場完全現代化』的觀察與推論分開，尋找店家、居民與其他空間證據。","刪除照片避免誤判。","只問政府是否同意這個結論。"],"B","局部觀察不能直接支撐整體結論，應標示推論跳躍並補充不同位置與群體的資料。","觀察與推論"),
("研究車站影響地方，資料含建站、改線、商店開設與拆遷日期。建立解釋時最適當的是？",["依年份排列後直接宣稱前者造成後者。","只選最能支持車站功勞的日期。","先建立時間線，再檢查中介機制、替代原因與不同群體的影響。","把所有日期視為同一事件。"],"C","時間線是研究骨架，不自動等於因果；還要檢查機制、替代解釋和證據範圍。","時間線與因果"),
("展板只能放四份資料，其中兩份是官方建設成果，兩份是居民搬遷經驗。最佳安排是？",["只放官方資料，畫面會比較一致。","只放居民資料，因為官方資料一定有偏見。","並置兩類資料，標記來源、觀點與互相支持或衝突之處，並寫出尚待查證的問題。","把兩類資料混成沒有來源的摘要。"],"C","展演應讓觀眾看見多方證據與限制，而不是用版面一致性消除觀點差異。","展演與多方證據"),
("舊地圖有一條河道，現代地圖沒有，現場只見排水溝。提出解釋前應？",["直接判定河道已被填平。","確認地圖年代、比例、河道改道與排水工程，並用地籍、照片或訪談提出可檢驗的多個可能。","以現代地圖為唯一真相。","把排水溝當成古代河道的確定證明。"],"B","歷史地景會因改道、填築和地圖尺度改變；需先確認來源條件，再提出有界解釋。","地圖與地景"),
("小組只訪談白天營業店家，卻想推論夜間攤販和居民的街區看法。報告應如何寫？",["照樣宣稱代表所有人。","把店家訪談刪除，因為樣本不完整。","說明時段與職業樣本偏差，限制結論，並補訪不同時間和群體。","用網路留言代替所有田野資料。"],"C","樣本的時間和角色範圍決定可推論對象；限制要明寫，並用補樣本改善。","樣本與代表性"),
("新資料顯示某地曾繁榮、後來衰退，近年因文化活動部分復甦。最謹慎的報告結論是？",["地方一直繁榮，所以不必討論衰退。","文化活動已讓所有居民恢復相同利益。","在限定時段與資料範圍內，描述不同階段的變化，並指出哪些群體和因果仍需補證。","只用最近的活動照片代表整段歷史。"],"C","地方變遷可能有多個階段和群體差異；結論應保留時間、證據與不確定性。","變遷結論"),
]
SOURCES=[{"url":"https://www.yacjh.kh.edu.tw/upload/221/101_30637/114%E4%B8%8B%E5%AD%B8%E6%9C%9F%E7%AC%AC%E4%B8%80%E6%AC%A1%E6%AE%B5%E8%80%83%E4%B8%89%E5%B9%B4%E7%B4%9A%E7%9A%84%E7%A4%BE%E6%9C%83.pdf","title":"高雄市立鹽埕國民中學公開段考社會科；僅研究資料判讀、時序與歷史推理題型，未複製原題。","year":"114","locator":"公開段考社會科 PDF；第 1 題至第 10 題型範圍：資料判讀、時序與因果界線","observedPattern":"由多種材料要求學生界定問題、證據範圍與歷史結論。"},{"url":"https://affairs.kh.edu.tw/1126/upload/file_list/149","title":"高雄市立文府國民中學公開社會科試題入口；僅研究多資料互證題型，未複製原題。","year":"113-114","locator":"公開試題與解答入口；第 1 題至第 10 題型範圍：探究、時序與多重證據","observedPattern":"比較地圖、文字與角色經驗，區分直接觀察、推論與待補證主張。"},{"url":"https://www.dwm.kh.edu.tw/view/index.php?MainMenuId=64182&MainType=0&SubMenuId=64184&SubType=104&WebID=344","title":"高雄市立大灣國民中學公開段考試題入口；僅研究地方探究與多方角色題型，未複製原題。","year":"113-114","locator":"公開段考試題入口；第 1 題至第 10 題型範圍：地方史、社會變遷與多方角色","observedPattern":"從地方材料分析樣本、證據與群體差異，不以單一來源包辦結論。"}]
def refs():return[{**x,"subject":"social","reuseDecision":"pattern-only","status":"recorded","locatorLevel":"paper"}for x in SOURCES]
targets=["A","B","C","D","A","B","C","D","B","C"]
for i,(prompt,opts,ans,reason,focus) in enumerate(ITEMS,1):
 p=OUT/f"question-social-content-hist-j-{i}.json";d=json.loads(p.read_text(encoding="utf-8"));assert d["lessonId"]==LESSON and d["knowledgeIds"]==[KG]
 target=targets[i-1];correct=opts[ord(ans)-65];rest=[x for j,x in enumerate(opts) if j != ord(ans)-65];ti=ord(target)-65;ordered=rest[:ti]+[correct]+rest[ti:]
 d["prompt"]=prompt;d["options"]=[{"id":chr(65+j),"text":x}for j,x in enumerate(ordered)];d["answer"]={"value":target,"explanation":f"本題聚焦「{focus}」。{reason} 正確答案為選項 {target}：「{correct}」。"};d["solutionStrategy"]=f"先用{focus}界定問題、來源、樣本、倫理與結論，再區分觀察、推論和待補證據；{reason}"
 d["solutionSteps"]=[f"讀題定位：圈出研究問題、資料、參與者與任務，確認本題正在檢核「{focus}」。","建立判準：把問題範圍、資料來源、樣本限制、倫理和結論強度分層。",f"核對正解：選項 {target}「{correct}」符合題幹，因為{reason}","逐項排除：檢查其餘選項是否把單一觀察放大、忽略來源與同意，或把時間順序誤當成因果。","結論回查：重新核對時間、地點、對象與證據強度；新增材料後要重新檢查，不能只沿用答案字母。"]
 d["examPatternRefs"]=refs();d["updatedAt"]="2026-09-13";d["reviewStatus"]="draft";d["provenance"]["authoringNote"]="依官方課綱、歷 J 知識圖譜及三所公立學校公開社會科試題的歷史探究、資料判讀與多方證據能力方向獨立改寫；未複製原題文字、選項、圖片或答案，待逐題學科與 Terra 複核。";p.write_text(json.dumps(d,ensure_ascii=False,indent=2)+"\n",encoding="utf-8")
print(f"rewrote {len(ITEMS)} independent questions for {LESSON}")
